<template>
  <AdminLayout>
    <main class="mx-auto max-w-7xl space-y-6" aria-labelledby="billing-title">
      <header class="rounded-2xl bg-slate-900 p-5 text-white shadow-sm sm:p-7"><p class="text-xs font-bold uppercase tracking-[.16em] text-blue-300">CONSULTA DE PEDIDOS</p><h1 id="billing-title" class="mt-1 text-3xl font-black">Facturación</h1><p class="mt-2 max-w-2xl text-sm text-slate-300">Revisa los datos que el cliente solicitó para su comprobante. La emisión se realiza manualmente fuera de esta bandeja.</p></header>
      <section class="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm" aria-label="Filtros de facturación"><form class="grid gap-3 sm:grid-cols-2 lg:grid-cols-6" @submit.prevent="load(1)">
        <label class="text-sm font-semibold text-slate-700 lg:col-span-2">Número de pedido o cliente<input v-model.trim="filters.search" class="field mt-1" placeholder="Número o nombre" /></label>
        <label class="text-sm font-semibold text-slate-700">Tipo solicitado<select v-model="filters.receipt_type" class="field mt-1"><option value="">Todos</option><option value="boleta">Boleta</option><option value="factura">Factura</option></select></label>
        <label class="text-sm font-semibold text-slate-700">Desde<input v-model="filters.date_from" type="date" class="field mt-1" /></label>
        <label class="text-sm font-semibold text-slate-700">Hasta<input v-model="filters.date_to" type="date" class="field mt-1" /></label>
        <label class="flex items-end gap-2 pb-2 text-sm font-semibold text-slate-700"><input v-model="filters.missing_data" type="checkbox" class="h-4 w-4 accent-blue-700" />Datos faltantes</label>
        <div class="flex gap-2 sm:col-span-2 lg:col-span-6"><Button type="submit" label="Aplicar filtros" icon="pi pi-filter" :disabled="loading" /><Button type="button" label="Limpiar" severity="secondary" outlined :disabled="loading" @click="clear" /></div>
      </form></section>
      <p v-if="error" class="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-900" role="alert">{{ error }}</p>
      <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm" aria-label="Pedidos para consulta de facturación">
        <div v-if="loading" class="p-10 text-center text-slate-600" role="status"><i class="pi pi-spin pi-spinner mr-2"></i>Cargando pedidos…</div>
        <div v-else-if="!rows.length" class="p-10 text-center text-slate-600"><i class="pi pi-file text-3xl text-slate-300"></i><p class="mt-2 font-semibold">No hay pedidos para estos filtros</p></div>
        <div v-else class="overflow-x-auto"><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="p-4">Pedido / fecha</th><th class="p-4">Cliente</th><th class="p-4">Solicitud</th><th class="p-4">Receptor</th><th class="p-4 text-right">Total</th><th class="p-4">Pago</th><th class="p-4">Datos</th><th class="p-4"></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-t border-slate-100 hover:bg-slate-50"><td class="p-4"><b>{{ row.order_number }}</b><span class="mt-1 block text-xs text-slate-500">{{ formatDate(row.created_at) }}</span></td><td class="p-4">{{ row.customer_name }}</td><td class="p-4">{{ receiptLabel(row.requested_receipt_type) }}</td><td class="p-4"><span>{{ row.requested_recipient_name || 'No registrado' }}</span><small v-if="row.requested_identity_number" class="block text-slate-500">{{ row.requested_identity_type }} · {{ row.requested_identity_number }}</small></td><td class="p-4 text-right font-semibold">S/ {{ money(row.total) }}</td><td class="p-4">{{ paymentLabel(row.payment_status) }}</td><td class="p-4"><Tag :severity="row.receipt_data_missing ? 'warn' : 'success'" :value="row.receipt_data_missing ? 'Revisar datos' : 'Solicitud registrada'" /></td><td class="p-4 text-right"><Button label="Consultar" icon="pi pi-eye" size="small" outlined @click="openDetail(row)" /></td></tr></tbody></table></div>
        <footer v-if="pagination.total" class="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 p-4 text-sm"><span>Mostrando {{ pagination.from }}–{{ pagination.to }} de {{ pagination.total }}</span><div class="flex gap-2"><Button label="Anterior" severity="secondary" outlined size="small" :disabled="loading || pagination.current_page <= 1" @click="load(pagination.current_page - 1)" /><Button label="Siguiente" severity="secondary" outlined size="small" :disabled="loading || pagination.current_page >= pagination.last_page" @click="load(pagination.current_page + 1)" /></div></footer>
      </section>
      <div v-if="detailOpen" class="fixed inset-0 z-[80] flex items-center justify-center bg-slate-950/60 p-3" role="presentation" @click.self="detailOpen = false"><section class="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white shadow-2xl" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="flex items-start justify-between gap-3 border-b p-5"><div><p class="text-xs font-bold uppercase tracking-wide text-blue-700">Consulta de Facturación</p><h2 id="detail-title" class="mt-1 text-2xl font-black">{{ detail?.order_number || 'Pedido' }}</h2></div><Button icon="pi pi-times" severity="secondary" text aria-label="Cerrar detalle" @click="detailOpen = false" /></header><div v-if="detailLoading" class="p-8 text-center" role="status">Cargando detalle…</div><div v-else-if="detail" class="space-y-5 p-5"><p class="rounded-lg bg-blue-50 p-3 text-sm text-blue-900">{{ detail.receipt_status === 'requested_not_issued' ? 'Comprobante solicitado; aún no emitido.' : 'Datos de comprobante no registrados.' }}</p><dl class="grid gap-3 sm:grid-cols-2"><div><dt class="label">Cliente</dt><dd>{{ detail.customer_name }}</dd></div><div><dt class="label">Fecha del pedido</dt><dd>{{ formatDate(detail.created_at) }}</dd></div><div><dt class="label">Tipo solicitado</dt><dd>{{ receiptLabel(detail.requested_receipt_type) }}</dd></div><div><dt class="label">Estado de pago</dt><dd>{{ paymentLabel(detail.payment_status) }}</dd></div><div><dt class="label">Receptor</dt><dd>{{ detail.requested_recipient_name || 'No registrado' }}</dd></div><div><dt class="label">Documento</dt><dd>{{ detail.requested_identity_type && detail.requested_identity_number ? `${detail.requested_identity_type} · ${detail.requested_identity_number}` : 'No registrado' }}</dd></div><div><dt class="label">Correo</dt><dd>{{ detail.requested_receipt_email || 'No registrado' }}</dd></div><div><dt class="label">Dirección de facturación</dt><dd>{{ detail.requested_billing_address || 'No registrada' }}</dd></div><div><dt class="label">Total del pedido</dt><dd class="font-bold">S/ {{ money(detail.total) }}</dd></div></dl><div><h3 class="mb-2 font-bold">Productos</h3><ul class="divide-y rounded-lg border"> <li v-for="(item, index) in detail.items || []" :key="index" class="flex justify-between gap-3 p-3 text-sm"><span>{{ item.quantity }} × {{ item.product_name }}</span><span>S/ {{ money(item.subtotal) }}</span></li></ul></div><p v-if="detailError" class="text-sm text-red-700" role="alert">{{ detailError }}</p></div></section></div>
    </main>
  </AdminLayout>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue';
import { useToast } from 'primevue/usetoast';
import api from '@/api';
import AdminLayout from '@/layouts/AdminLayout.vue';
import Button from 'primevue/button';
import Tag from 'primevue/tag';

const toast = useToast();
const filters = reactive({ search: '', receipt_type: '', date_from: '', date_to: '', missing_data: false });
const rows = ref([]), pagination = ref({}), loading = ref(false), error = ref('');
const detailOpen = ref(false), detailLoading = ref(false), detail = ref(null), detailError = ref('');
function money(value) { return Number(value || 0).toLocaleString('es-PE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function formatDate(value) { return value ? new Intl.DateTimeFormat('es-PE', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'America/Lima' }).format(new Date(value)) : '—'; }
function receiptLabel(value) { return value === 'boleta' ? 'Boleta de venta' : value === 'factura' ? 'Factura' : 'No registrado'; }
function paymentLabel(value) { return ({ pending: 'Pendiente', partial: 'Parcial', approved: 'Aprobado', rejected: 'Rechazado', refunded: 'Reembolsado' })[value] || 'Sin estado'; }
async function load(page = 1) { loading.value = true; error.value = ''; try { const params = Object.fromEntries(Object.entries({ ...filters, page }).filter(([, value]) => value !== '' && value !== false)); const response = (await api.get('/billing/orders', { params })).data; rows.value = response.data || []; pagination.value = response.meta || {}; } catch (exception) { error.value = exception.response?.data?.message || 'No se pudo cargar la bandeja.'; } finally { loading.value = false; } }
function clear() { Object.assign(filters, { search: '', receipt_type: '', date_from: '', date_to: '', missing_data: false }); load(1); }
async function openDetail(row) { detail.value = null; detailError.value = ''; detailOpen.value = true; detailLoading.value = true; try { detail.value = (await api.get(`/billing/orders/${row.id}`)).data.data; } catch (exception) { detailError.value = exception.response?.data?.message || 'No se pudo cargar el pedido.'; toast.add({ severity: 'error', summary: 'Detalle no disponible', detail: detailError.value, life: 4000 }); } finally { detailLoading.value = false; } }
onMounted(() => load());
</script>

<style scoped>
.field{min-height:2.75rem;width:100%;border:1px solid #cbd5e1;border-radius:.625rem;background:#fff;padding:.625rem .75rem;color:#0f172a}.field:focus-visible{outline:2px solid #2563eb;outline-offset:2px}.label{font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:#64748b}.label+dd{margin-top:.25rem;overflow-wrap:anywhere;color:#0f172a}
</style>
